import{_ as t,c as a,a as o,o as r}from"./app.80edbbb0.js";const m=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[{"level":2,"title":"Create your first goal","slug":"create-your-first-goal"},{"level":2,"title":"Choosing a goal type","slug":"choosing-a-goal-type"},{"level":2,"title":"Feeding it data","slug":"feeding-it-data"},{"level":2,"title":"Your first week","slug":"your-first-week"},{"level":2,"title":"What happens on an eep day","slug":"what-happens-on-an-eep-day"},{"level":2,"title":"Official guides","slug":"official-guides"},{"level":2,"title":"Learn more","slug":"learn-more"}],"relativePath":"getting-started.md"}'),n={name:"getting-started.md"};function i(s,e,l,h,g,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-hidden="true">#</a></h1><p>New to Beeminder? This page walks you through getting your first goal off the ground. If you&#39;re still wondering what Beeminder even is, start with <a href="./what-is-beeminder.html">What Is Beeminder?</a> and come back here when you&#39;re ready to commit to something.</p><h2 id="create-your-first-goal" tabindex="-1">Create your first goal <a class="header-anchor" href="#create-your-first-goal" aria-hidden="true">#</a></h2><ol><li><strong>Sign up.</strong> Create a free account at <a href="https://www.beeminder.com/" target="_blank" rel="noopener noreferrer">beeminder.com</a>. You don&#39;t put any money down to sign up; pledges only come into play once you create a goal and start derailing.</li><li><strong>Pick something to track.</strong> The best first goal is small, concrete, and measurable every day or two, something you can honestly say yes-or-no (or count) at the end of the day. &quot;Write 200 words,&quot; &quot;walk 5,000 steps,&quot; &quot;no more than 30 minutes of social media.&quot; Save the life-changing mega-goals for later; you&#39;re learning how the tool feels.</li><li><strong>Choose a goal type.</strong> Beeminder&#39;s <a href="https://www.beeminder.com/new" target="_blank" rel="noopener noreferrer">goal gallery</a> offers a handful of shapes (see <a href="#choosing-a-goal-type">Choosing a goal type</a> below). When in doubt, pick <strong>Do More</strong>. It&#39;s the workhorse and fits most starter goals.</li><li><strong>Set your rate.</strong> Tell Beeminder how much you&#39;ll do and how often, like &quot;1 per day&quot; or &quot;10 per week.&quot; This becomes your <a href="./what-is-beeminder.html">bright red line</a>. Start gentler than you think you should; you can always ramp up later, and an aggressive rate is the most common reason beginners derail.</li><li><strong>Set your pledge.</strong> Every goal starts at <strong>$0</strong>. The first time you go off track you pledge <strong>$5</strong>, and each later derailment bumps it up a schedule ($0 \u2192 $5 \u2192 $10 \u2192 $30 \u2192 \u2026) until the sting is enough to change your behavior. See <a href="https://www.beeminder.com/money" target="_blank" rel="noopener noreferrer">how the money works</a> for the full schedule and how to cap it.</li><li><strong>Create the goal.</strong> That&#39;s it: you now have a graph with a bright red line, ready for its first datapoints.</li></ol><h2 id="choosing-a-goal-type" tabindex="-1">Choosing a goal type <a class="header-anchor" href="#choosing-a-goal-type" aria-hidden="true">#</a></h2><p>You don&#39;t need to memorize these; the <a href="https://www.beeminder.com/new" target="_blank" rel="noopener noreferrer">gallery</a> explains each as you go. The two broad shapes are:</p><ul><li><strong>Doing more of something.</strong> Writing, exercising, studying, shipping code. Your datapoints add up and you commit to a minimum rate. <strong>Do More</strong> and <strong>Odometer</strong> goals work this way.</li><li><strong>Doing less of something.</strong> Screen time, calories, cigarettes, takeout. You commit to staying <em>under</em> a ceiling. <strong>Whittle Down</strong> and <strong>Do Less</strong> style goals handle these.</li></ul><p>If your first pick turns out wrong, that&#39;s fine: make a new goal. Spinning up goals is cheap and part of learning what&#39;s worth beeminding.</p><h2 id="feeding-it-data" tabindex="-1">Feeding it data <a class="header-anchor" href="#feeding-it-data" aria-hidden="true">#</a></h2><p>A goal is only as good as the data you put into it. You have two options:</p><ul><li><strong>Enter datapoints by hand.</strong> Type the number into the goal page, the mobile app, or even by email or <a href="https://www.beeminder.com/apps" target="_blank" rel="noopener noreferrer">Apple Watch</a>. Quick and works for anything.</li><li><strong>Connect an integration.</strong> Beeminder pulls data automatically from dozens of services: fitness trackers, time loggers, to-do apps, and more. Wiring one up means you never have to remember to log. See <a href="./integrations.html">Integrations</a> for the full list, and <a href="./use-cases.html">Use Cases</a> for ideas on what to track with them.</li></ul><p>Manual entry is the fastest way to <em>start</em>; automating it later is the best way to make a goal stick.</p><h2 id="your-first-week" tabindex="-1">Your first week <a class="header-anchor" href="#your-first-week" aria-hidden="true">#</a></h2><p>A brand-new goal <em>can</em> derail in its first week, so it&#39;s worth easing yourself in. When you create a goal, Beeminder gives you two ways to take the early sting off:</p><ul><li><strong>Start with safety buffer.</strong> Give the goal a few days of initial leeway so the bright red line doesn&#39;t catch up to you while you&#39;re finding your feet.</li><li><strong>Hold the pledge at $0 for the first week.</strong> Tell Beeminder to keep the goal at a $0 pledge while you settle on your stakes, so an early stumble costs nothing.</li></ul><p>Either way, set your rate thoughtfully at the start. The same <a href="https://help.beeminder.com/article/82-the-akrasia-horizon" target="_blank" rel="noopener noreferrer">akrasia horizon</a> that stops you from weaseling out later also applies to changes you make now: dialing a goal <em>easier</em> only takes effect about a week out, never right now. It&#39;s far easier to start gentle than to loosen an aggressive goal after the fact.</p><h2 id="what-happens-on-an-eep-day" tabindex="-1">What happens on an eep day <a class="header-anchor" href="#what-happens-on-an-eep-day" aria-hidden="true">#</a></h2><p>Eventually you&#39;ll hit an <strong>eep day</strong>: a day when you have to do the thing (or enter data) or you&#39;ll cross your bright red line and derail. When that happens:</p><ul><li><strong>Do the thing and report it.</strong> Get back on the right side of the line and you&#39;re safe until the next eep day.</li><li><strong>If you genuinely can&#39;t,</strong> you derail and your pledge is charged. Beeminder <em>wants</em> you to keep your money; the charge is a backstop, not the goal. If a derailment was due to a bug or something truly outside the spirit of your commitment, you can <a href="https://help.beeminder.com/article/97-legitimate-check-in-derailments" target="_blank" rel="noopener noreferrer">call a &quot;non-legit&quot; derailment</a>.</li></ul><p>Derailing isn&#39;t failing. Beeminder argues it&#39;s <a href="https://blog.beeminder.com/nailingit/" target="_blank" rel="noopener noreferrer"><em>nailing it</em></a>: paying up when you derail is a legitimate, built-in part of the service, not proof you blew it. A derailment doesn&#39;t necessarily mean your goal was wrong, either. Often it just means the stakes haven&#39;t climbed high enough to move you yet, which is exactly what the escalating pledge is there to fix. If you keep derailing on the same goal it&#39;s worth revisiting your rate, but a derailment on its own is the system doing its job.</p><h2 id="official-guides" tabindex="-1">Official guides <a class="header-anchor" href="#official-guides" aria-hidden="true">#</a></h2><p>When you want the canonical word from Beeminder itself, these are the best starting points:</p><ul><li><a href="https://blog.beeminder.com/newbees/" target="_blank" rel="noopener noreferrer"><strong>A Newbie Guide</strong></a> to getting started with Beeminder. (Called <em>newbee</em>, get it?)</li><li><a href="https://www.beeminder.com/overview" target="_blank" rel="noopener noreferrer"><strong>An Overview</strong></a> of what Beeminder is.</li><li><a href="https://blog.beeminder.com/glossary/" target="_blank" rel="noopener noreferrer"><strong>A Glossary</strong></a> of terms often used in Beeminder discussions and docs.</li><li><a href="https://www.beeminder.com/faq" target="_blank" rel="noopener noreferrer"><strong>An FAQ</strong></a> which gets into the technical details of specific goals, derailments, etc.</li><li><a href="https://help.beeminder.com/" target="_blank" rel="noopener noreferrer"><strong>A Help Section</strong></a> with even more information and how-to guides.</li></ul><h2 id="learn-more" tabindex="-1">Learn more <a class="header-anchor" href="#learn-more" aria-hidden="true">#</a></h2><ul><li><a href="./what-is-beeminder.html">What Is Beeminder?</a> covers the concepts and vocabulary behind the line.</li><li><a href="./philosophy.html">The Beeminder Philosophy</a> explains why putting money on the line works.</li><li><a href="./use-cases.html">Use Cases</a> has ideas for what to beemind.</li><li><a href="./integrations.html">Integrations</a> connects the apps you already use.</li></ul>',25)])])}var p=t(n,[["render",i]]);export{m as __pageData,p as default};
